create table if not exists public.recording_sessions(id uuid primary key default gen_random_uuid(),pelada_id uuid not null references public.peladas(id) on delete cascade,admin_id uuid not null references public.profiles(id),device_id text not null,started_at timestamptz not null,ended_at timestamptz,duration_ms bigint not null default 0,local_file_id text,uploaded_file text,mime_type text,server_time_offset_ms integer not null default 0,status text not null default 'READY' check(status in('READY','RECORDING','FINISHED','PROCESSING','COMPLETED','ERROR')),upload_status text not null default 'LOCAL' check(upload_status in('LOCAL','PENDING','UPLOADING','UPLOADED','ERROR')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.recording_fragments(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.recording_sessions(id) on delete cascade,sequence_number integer not null check(sequence_number>=0),started_at timestamptz not null,duration_ms integer not null check(duration_ms>=0),storage_path text not null,mime_type text not null,byte_size bigint not null check(byte_size>=0),sha256 text,upload_status text not null default 'UPLOADED' check(upload_status in('PENDING','UPLOADING','UPLOADED','ERROR')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(session_id,sequence_number)); create table if not exists public.recording_cuts(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.recording_sessions(id) on delete cascade,event_id uuid not null references public.pelada_eventos_partida(id) on delete cascade,clip_start_ms bigint not null check(clip_start_ms>=0),clip_end_ms bigint not null check(clip_end_ms>clip_start_ms),status text not null default 'PENDING' check(status in('PENDING','PROCESSING','COMPLETED','ERROR','CANCELLED')),output_path text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id)); create index if not exists recording_sessions_pelada_idx on public.recording_sessions(pelada_id,started_at desc); create index if not exists recording_fragments_session_idx on public.recording_fragments(session_id,sequence_number); create index if not exists recording_cuts_session_idx on public.recording_cuts(session_id,created_at desc); alter table public.recording_sessions enable row level security; alter table public.recording_fragments enable row level security; alter table public.recording_cuts enable row level security; create policy recording_sessions_superadmin_read on public.recording_sessions for select to authenticated using(public.is_superadmin()); create policy recording_fragments_superadmin_read on public.recording_fragments for select to authenticated using(public.is_superadmin()); create policy recording_cuts_superadmin_read on public.recording_cuts for select to authenticated using(public.is_superadmin()); insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pelada-gravacoes','pelada-gravacoes',false,52428800,array['video/webm','video/mp4']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types; drop policy if exists pelada_gravacoes_superadmin on storage.objects; create policy pelada_gravacoes_superadmin on storage.objects for all to authenticated using(bucket_id='pelada-gravacoes' and public.is_superadmin()) with check(bucket_id='pelada-gravacoes' and public.is_superadmin()); create or replace function public.superadmin_iniciar_gravacao(p_pelada_id uuid,p_device_id text,p_started_at timestamptz,p_server_time_offset_ms integer default 0) returns public.recording_sessions language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; begin if not public.is_superadmin() then raise exception 'Acesso negado'; end if; select * into v_session from public.recording_sessions where pelada_id=p_pelada_id and status='RECORDING' order by started_at desc limit 1 for update; if found then return v_session; end if; insert into public.recording_sessions(pelada_id,admin_id,device_id,started_at,server_time_offset_ms,status,upload_status) values(p_pelada_id,auth.uid(),p_device_id,p_started_at,p_server_time_offset_ms,'RECORDING','LOCAL') returning * into v_session; insert into public.pelada_dispositivos(pelada_id,user_id,device_id,mode,status,server_time_offset_ms) values(p_pelada_id,auth.uid(),p_device_id,'CAMERA','ONLINE',p_server_time_offset_ms) on conflict(pelada_id,device_id) do update set user_id=excluded.user_id,mode='CAMERA',status='ONLINE',server_time_offset_ms=excluded.server_time_offset_ms,last_seen_at=now(); update public.pelada_controles set recording_session_id=v_session.id,recording_started_at=p_started_at,device_camera_online=true,updated_at=now() where pelada_id=p_pelada_id; return v_session; end $$; create or replace function public.superadmin_sinalizar_gravacao(p_session_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; begin select * into v_session from public.recording_sessions where id=p_session_id for update; if not public.is_superadmin() or v_session.admin_id<>auth.uid() then raise exception 'Acesso negado'; end if; if v_session.status<>'RECORDING' then raise exception 'Gravação não está ativa'; end if; update public.recording_sessions set updated_at=now() where id=p_session_id; update public.pelada_controles set device_camera_online=true,updated_at=now() where pelada_id=v_session.pelada_id and recording_session_id=v_session.id; update public.pelada_dispositivos set status='ONLINE',last_seen_at=now() where pelada_id=v_session.pelada_id and device_id=v_session.device_id; end $$; create or replace function public.superadmin_registrar_fragmento_gravacao(p_session_id uuid,p_sequence_number integer,p_started_at timestamptz,p_duration_ms integer,p_storage_path text,p_mime_type text,p_byte_size bigint,p_sha256 text default null) returns public.recording_fragments language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; v_fragment public.recording_fragments; begin select * into v_session from public.recording_sessions where id=p_session_id for update; if not public.is_superadmin() or v_session.admin_id<>auth.uid() then raise exception 'Acesso negado'; end if; if v_session.status not in('RECORDING','FINISHED') then raise exception 'Sessão indisponível'; end if; insert into public.recording_fragments(session_id,sequence_number,started_at,duration_ms,storage_path,mime_type,byte_size,sha256,upload_status) values(p_session_id,p_sequence_number,p_started_at,p_duration_ms,p_storage_path,p_mime_type,p_byte_size,p_sha256,'UPLOADED') on conflict(session_id,sequence_number) do update set started_at=excluded.started_at,duration_ms=excluded.duration_ms,storage_path=excluded.storage_path,mime_type=excluded.mime_type,byte_size=excluded.byte_size,sha256=excluded.sha256,upload_status='UPLOADED',updated_at=now() returning * into v_fragment; update public.recording_sessions set upload_status='UPLOADING',updated_at=now() where id=p_session_id; return v_fragment; end $$; create or replace function public.superadmin_finalizar_gravacao(p_session_id uuid,p_ended_at timestamptz) returns public.recording_sessions language plpgsql security definer set search_path='' as $$ declare v_session public.recording_sessions; begin select * into v_session from public.recording_sessions where id=p_session_id for update; if not public.is_superadmin() or v_session.admin_id<>auth.uid() then raise exception 'Acesso negado'; end if; if v_session.status='RECORDING' then update public.recording_sessions set ended_at=p_ended_at,duration_ms=greatest(0,extract(epoch from(p_ended_at-started_at))*1000)::bigint,status='FINISHED',upload_status=case when exists(select 1 from public.recording_fragments where session_id=p_session_id) then 'PENDING' else 'LOCAL' end,updated_at=now() where id=p_session_id returning * into v_session; end if; update public.pelada_controles set recording_session_id=null,recording_started_at=null,device_camera_online=false,updated_at=now() where pelada_id=v_session.pelada_id and recording_session_id=p_session_id; update public.pelada_dispositivos set status='OFFLINE',last_seen_at=now() where pelada_id=v_session.pelada_id and device_id=v_session.device_id; return v_session; end $$; create or replace function public.superadmin_solicitar_corte_gravacao(p_event_id uuid) returns public.recording_cuts language plpgsql security definer set search_path='' as $$ declare v_event public.pelada_eventos_partida; v_cut public.recording_cuts; v_after bigint; begin select * into v_event from public.pelada_eventos_partida where id=p_event_id; if not public.is_superadmin() or v_event.recording_session_id is null or v_event.status<>'ACTIVE' or v_event.type not in('GOAL','HIGHLIGHT') then raise exception 'Evento indisponível para corte'; end if; v_after=case when v_event.type='GOAL' then 8000 else 5000 end; insert into public.recording_cuts(session_id,event_id,clip_start_ms,clip_end_ms,status) values(v_event.recording_session_id,v_event.id,greatest(0,coalesce(v_event.recording_offset_ms,0)-10000),coalesce(v_event.recording_offset_ms,0)+v_after,'PENDING') on conflict(event_id) do update set clip_start_ms=excluded.clip_start_ms,clip_end_ms=excluded.clip_end_ms,status='PENDING',error_message=null,updated_at=now() returning * into v_cut; return v_cut; end $$; revoke all on function public.superadmin_iniciar_gravacao(uuid,text,timestamptz,integer),public.superadmin_sinalizar_gravacao(uuid),public.superadmin_registrar_fragmento_gravacao(uuid,integer,timestamptz,integer,text,text,bigint,text),public.superadmin_finalizar_gravacao(uuid,timestamptz),public.superadmin_solicitar_corte_gravacao(uuid) from public; grant execute on function public.superadmin_iniciar_gravacao(uuid,text,timestamptz,integer),public.superadmin_sinalizar_gravacao(uuid),public.superadmin_registrar_fragmento_gravacao(uuid,integer,timestamptz,integer,text,text,bigint,text),public.superadmin_finalizar_gravacao(uuid,timestamptz),public.superadmin_solicitar_corte_gravacao(uuid) to authenticated;
